func parseCount(r io.Reader) (map[string]int, error) {
	rd := csv.NewReader(r)
	out := map[string]int{}
	for {
		rec, err := rd.Read()
		if err == io.EOF { return out, nil }
		if err != nil { return nil, err }
		n, err := strconv.Atoi(rec[1])
		if err != nil { return nil, fmt.Errorf("bad quantity for %s: %w", rec[0], err) }
		out[rec[0]] = n
	}
}

