export function currentStreak(days: string[], today: string): number {
  const set = new Set(days);
  let n = 0, d = parseISO(today);
  if (!set.has(today)) d = subDays(d, 1);
  while (set.has(format(d, 'yyyy-MM-dd'))) { n++; d = subDays(d, 1); }
  return n;
}

